    ]
  }
]
}

{
"intro": "Proceda a generar una orden de compra desde un pedido de compra validado.",
"pasos": [
  {
    "n": 1,
    "id": "compras.generar-orden-de-compra-desde-pedido#1",
    "texto": "Ingrese al escenario de **Pedidos de Compra**.",
    "fotos": [
      "cd0bf33e79cd"
    ]
